export function evaluate({ inputs, time }) {
  const u = Number(inputs.launchSpeed);
  const g = Number(inputs.gravity);
  const m = Number(inputs.mass);
  const tTop = u / g;
  const tEnd = 2 * u / g;
  const t = sdk.clamp(Number(time) || 0, 0, tEnd);
  const v = u - g * t;
  const h = Math.max(0, u * t - g * t * t / 2);
  const a = -g;
  const F = m * g;
  const apexHeight = u * u / (2 * g);
  let state;
  if (t <= 1e-9) state = 'Ready to toss';
  else if (Math.abs(t - tTop) < 0.003) state = 'At the top';
  else if (t >= tEnd - 1e-9) state = 'Back at launch height';
  else if (t < tTop) state = 'Rising';
  else state = 'Falling';

  const objs = [];
  // Left scene: the motion
  const axX = 60, axY = 360, axLen = 290;
  const Y = (y) => axY - (y / 2.2) * axLen;
  const ballX = 125;
  const ballD = 18;
  const by = Y(h);
  objs.push(sdk.text('leftTitle', 160, 22, 'The motion', { align: 'middle' }));
  objs.push(sdk.text('stateLine', 205, 50, state, { align: 'middle', role: 'output' }));
  objs.push(sdk.axis('heightAxis', { x: axX, y: axY, length: axLen, orientation: 'y', min: 0, max: 2.2, ticks: [0, 0.5, 1, 1.5, 2], label: 'Height above launch', unit: 'm' }));
  objs.push(...[].concat(sdk.groundMark('launchMark', 135, Y(0), 80)));
  objs.push(sdk.circle('ball', ballX, by, ballD, { role: 'neutral' }));
  const vabs = Math.abs(v);
  if (vabs > 1e-9) {
    const up = v >= 0;
    const edge = ballD / 2 + 3;
    const startY = up ? by - edge : by + edge;
    objs.push(...sdk.vector('velArrow', { x: ballX, y: startY }, { value: vabs, direction: up ? 'up' : 'down' }, { scale: 10, minLength: 8, label: 'v', role: 'input' }));
  }
  objs.push(...sdk.vector('accArrow', { x: ballX + 32, y: by }, { value: g, direction: 'down' }, { scale: 4, label: 'a', role: 'warning' }));
  const vTxt = Math.abs(v) < 0.005 ? '0.00' : (v > 0 ? '+' : '-') + sdk.format(Math.abs(v), 2);
  const lines = ['v = ' + vTxt + ' m/s', 'a = -' + sdk.format(g, 1) + ' m/s²', 'F = ' + sdk.format(F, 1) + ' N down'];
  objs.push(...sdk.callout(180, sdk.clamp(by - 40, 62, 300), lines, { id: 'motionCallout' }));

  // Right scene: velocity over time
  const gx = 400, gy = 360, gw = 220, gh = 290;
  const X = (tt) => gx + (tt / 1.8) * gw;
  const V = (vv) => gy - ((vv + 5.5) / 11) * gh;
  objs.push(sdk.text('rightTitle', 500, 22, 'Velocity over time', { align: 'middle' }));
  objs.push(sdk.axis('timeAxis', { x: gx, y: gy, length: gw, orientation: 'x', min: 0, max: 1.8, ticks: [0, 0.6, 1.2, 1.8], label: 'Time since launch', unit: 's' }));
  objs.push(sdk.axis('velAxis', { x: gx, y: gy, length: gh, orientation: 'y', min: -5.5, max: 5.5, ticks: [-4, -2, 0, 2, 4], label: 'Velocity', unit: 'm/s' }));
  objs.push(sdk.line('zeroLine', gx, V(0), gx + gw, V(0), { opacity: 0.3 }));
  objs.push(sdk.polyline('vFuture', [[X(0), V(u)], [X(tEnd), V(-u)]], { opacity: 0.3, role: 'input' }));
  if (t > 1e-6) objs.push(sdk.polyline('vTrace', [[X(0), V(u)], [X(t), V(v)]], { role: 'input' }));
  const s0 = Math.max(0, t - 0.15), s1 = Math.min(tEnd, t + 0.15);
  objs.push(sdk.polyline('slopeSeg', [[X(s0), V(u - g * s0)], [X(s1), V(u - g * s1)]], { role: 'warning' }));
  objs.push(sdk.text('slopeLabel', sdk.clamp(X(t) + 12, gx + 10, 520), sdk.clamp(V(v) - 16, 76, 340), 'slope a = -g', { role: 'warning' }));
  objs.push(sdk.circle('vMarker', X(t), V(v), 11, { role: 'output' }));

  const q = { launchSpeed: u, gravity: g, mass: m, apexTime: tTop, apexHeight, height: h, velocity: v, acceleration: a, force: F, time: t };
  return {
    frame: {
      width: 640, height: 440, objects: objs,
      readouts: [
        { id: 'velocity', value: v },
        { id: 'acceleration', value: a },
        { id: 'force', value: F },
        { id: 'motionState', value: state }
      ]
    },
    quantities: q
  };
}
